      "2. 내 몸의 모든 염려 이 세상 고락간 나와 항상 같이하여 주시고 시험을 당할 때에 악마의 계교를 즉시 물리치사 나를 지키네",
      "3. 내 영혼 먹이시는 그 은혜 누리고 나 친히 주를 뵙기 원하네 내 맘을 다하여서 주님을 따르면 길이길이 나와 함께 계시리. 아멘."
