      "[후렴] 할렐루야 찬양하세 내 모든 죄 사함 받고 주 예수와 동행하니 그 어디나 하늘 나라",
      "2. 주의 얼굴 뵙기 전에 멀리 뵈던 하늘 나라 내 맘속에 이뤄지니 날로 날로 가깝도다",
      "3. 높은 산이 거친 들이 초막이나 궁궐이나 내 주 예수 모신 곳이 그 어디나 하늘 나라. 아멘."
